const input = $input.first().json || {};
const headers = input.headers || {};
const body = input.body || input;
const path = String(headers['x-n8n-webhook-path'] || headers['x-original-uri'] || '').toLowerCase();

const flowEnv = String($env.FLOW_ENV || 'staging').toLowerCase();
if (flowEnv !== 'staging') throw new Error('FLOW_ENV must be staging');

const expectedInstance = String($env.EVOLUTION_INSTANCE || 'mdoctor-staging').trim();
const instanceName = String(body.instance || body.instanceName || '').trim();
if (instanceName && instanceName !== expectedInstance) throw new Error(`instanceName mismatch: ${instanceName}`);

let event = String(body.event || body.type || '').toUpperCase().replace(/\./g, '_').replace(/-/g, '_');
if (!event) {
  if (path.includes('messages-upsert')) event = 'MESSAGES_UPSERT';
  else if (path.includes('messages-update')) event = 'MESSAGES_UPDATE';
  else if (path.includes('send-message')) event = 'SEND_MESSAGE';
  else if (path.includes('connection-update')) event = 'CONNECTION_UPDATE';
  else if (path.includes('qrcode-updated')) event = 'QRCODE_UPDATED';
  else event = 'UNKNOWN';
}

const allowed = new Set(['MESSAGES_UPSERT','MESSAGES_UPDATE','SEND_MESSAGE','CONNECTION_UPDATE','QRCODE_UPDATED']);
if (!allowed.has(event)) {
  return [{ json: { route: 'IGNORED_EVENT', event, correlationId: `evo-${Date.now()}`, log: { ignored: true } } }];
}

const data = body.data || body;
const key = data.key || body.key || {};
const message = data.message || body.message || {};
const remoteJid = String(key.remoteJid || data.remoteJid || '').trim();
const fromMe = Boolean(key.fromMe ?? data.fromMe ?? false);
const messageId = String(key.id || data.id || `${Date.now()}`);
const text = String(message.conversation || message.extendedTextMessage?.text || data.text || body.text || '').trim();
const correlationId = headers['x-correlation-id'] || headers['X-Correlation-Id'] || `evo-${event.toLowerCase()}-${Date.now()}`;
const idempotencyKey = headers['idempotency-key'] || headers['Idempotency-Key'] || messageId;
const inbound = event === 'MESSAGES_UPSERT' && !fromMe && Boolean(remoteJid);

return [{ json: {
  route: inbound ? 'INBOUND_MESSAGE' : 'EVENT_LOG',
  event, flowEnv, instanceName: instanceName || expectedInstance,
  correlationId, idempotencyKey, inbound, remoteJid, fromMe, text, messageId,
  n8nTypebotWebhook: String($env.N8N_TYPEBOT_WEBHOOK_URL || 'https://n8n-staging-staging-2dfe.up.railway.app/webhook/typebot-webhook').trim(),
  log: { event, remoteJid: remoteJid || null, fromMe, hasText: Boolean(text), messageId, path }
}}];

const ctx = $input.first().json;
let relayResult = null;
if ((ctx.text || '').toUpperCase().includes('STAGING_E2E_COMPLETE')) {
  const phone = ctx.remoteJid.replace(/\D/g, '').replace(/@.*/, '');
  const payload = {
    nome: `Paciente WhatsApp ${phone.slice(-4)}`,
    telefone: phone,
    cpf: '12345678909',
    email: `wa.${phone}@staging.invalid`,
    data_nascimento: '15/08/1988',
    condicao: 'hipertensao',
    medicacao: 'losartana 50mg',
    uso_continuo: 'sim',
    receita_anterior: 'sim',
    tempo_uso: '180 dias',
    sinais_alerta: 'NAO',
    lgpd: 'sim',
    consentimento: 'sim',
    from: phone,
    text: ctx.text,
    rawMessage: { messageId: ctx.idempotencyKey, channel: 'whatsapp-evolution', original: ctx.log }
  };
  relayResult = await this.helpers.httpRequest({
    method: 'POST',
    url: ctx.n8nTypebotWebhook,
    headers: {
      'Content-Type': 'application/json',
      'X-Correlation-Id': ctx.correlationId,
      'Idempotency-Key': ctx.idempotencyKey
    },
    body: payload,
    json: true,
    timeout: 30000
  });
}
return [{ json: { ...ctx, relayResult } }];
